import{_ as r,o as t,c as a,a2 as l}from"./chunks/framework.CHeM0PsO.js";const i="/img/ability_test.png",o="/img/MXNet_forum_questions.png",n="/img/Fin_xiaoice.png",s="/img/xiaoice_zhaopin_issue.jpg",h="/img/login_suggest.png",_=JSON.parse('{"title":"模拟面试","description":"","frontmatter":{},"headers":[],"relativePath":"interview/simulate_interview.md","filePath":"interview/simulate_interview.md","lastUpdated":null}'),p={name:"interview/simulate_interview.md"};function b(m,e,c,d,g,u){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="模拟面试" tabindex="-1">模拟面试 <a class="header-anchor" href="#模拟面试" aria-label="Permalink to &quot;模拟面试&quot;">​</a></h1><p>TODO:<a href="https://t.qidianla.com/1165227.html" target="_blank" rel="noreferrer">https://t.qidianla.com/1165227.html</a></p><p>TODO: <a href="https://t.qidianla.com/author/qdxy-pmjy" target="_blank" rel="noreferrer">https://t.qidianla.com/author/qdxy-pmjy</a></p><p>面试流程：专业面→跨岗位面→BOSS面→HR面 <a href="https://t.qidianla.com/1165227.html" target="_blank" rel="noreferrer">1</a></p><p><img src="'+i+'" alt="能力测试"></p><h2 id="电话面" tabindex="-1">电话面 <a class="header-anchor" href="#电话面" aria-label="Permalink to &quot;电话面&quot;">​</a></h2><p>对方对你做一个初步的了解，根据你的沟通交流、表达来看下逻辑思维能力如何。</p><h2 id="专业面" tabindex="-1">专业面 <a class="header-anchor" href="#专业面" aria-label="Permalink to &quot;专业面&quot;">​</a></h2><p>针对你的简历提问</p><h3 id="个人介绍" tabindex="-1">个人介绍 <a class="header-anchor" href="#个人介绍" aria-label="Permalink to &quot;个人介绍&quot;">​</a></h3><p>在这个环节，面试官的目的是想通过你的自我介绍，对你的综合能力进行一个试探性的摸底。</p><p>考察的范围包括但不限于：沟通表达能力，逻辑思维能力，自我认知，知识边界，思维格局，以及描述与简历的匹配度等。</p><p>也就是说，你的自我介绍就相当于你给面试官的第一印象，不管你在简历上写了什么。</p><p>所以，面试时请务必认真的做一个有诚意的自我介绍，介绍的核心请围绕：</p><p>【我是谁，我从哪里来，我要到哪里去，我想干什么，我能干什么】这几点展开，时间控制在5分钟以内为佳。<a href="https://www.zhihu.com/question/350672843/answer/1997174430" target="_blank" rel="noreferrer">11</a></p><h3 id="我自己的介绍" tabindex="-1">我自己的介绍 <a class="header-anchor" href="#我自己的介绍" aria-label="Permalink to &quot;我自己的介绍&quot;">​</a></h3><p>我叫蔡舒起，年龄23，现求职一份金融AI产品经理岗位。</p><ul><li>金融方面：2020届的山西大学金融学专业的毕业生，获得三好学生学业奖学金，拥有会计、证券、基金从业证书，毕业论文是用Python的Statsmodel库里的VAR模型完成的《中美股市的联动性分析》，提出百度股价被低估能上300USD的想法，实现后。现注意到百度股票主打AI第一股重新去香港上市。ToB和ToG业务强调服务,要随时响应客户需求，我的金融背景能快速学会用客户的语言进行业务沟通。<a href="https://cloud.ofweek.com/news/2020-11/ART-178801-8500-30469911.html" target="_blank" rel="noreferrer">8</a></li><li>AI方面：我的整个经历，大一参加数学建模了解了神经网络算法，后在网络金融课分享了鱼书的ppt，得知金融方面的非结构信息常用深度学习算法，之后阅读过二十几本人工智能相关书籍，在20年用4个月自学完了《动手学深度学习》预览版并动手翻译MXNet到PyTorch的GAN\\DCGAN，复现PyTorch、DJL等一系列深度学习移动端框架的Demo。</li><li>产品经理方面：虽然没有工作经历，但还是努力修炼了一系列的能力。战略能力上，在百度一面失败后，考虑到了百度开发者版的想法。沟通能力上，与MXNet的开发者交流无人社区冷淡情况。学习上，学习十余本产品有关的书，并自行总结了AI产品经理的工作内容和技能要求，用Docker部署成《To be AI PM》书。</li></ul><hr><p>OR</p><p>求职金融AI研报工作。</p><ul><li>金融方面：2020届的山西大学金融学专业的毕业生，获得三好学生&amp;学业奖学金，拥有会计、证券、基金从业证书，毕业论文是用Python的Statsmodel库里的VAR模型完成的《中美股市的联动性分析》，提出百度股价被低估能上300USD的想法，实现后。现注意到百度股票主打AI第一股重新去香港上市。</li><li>AI方面：我的整个经历，大一参加数学建模了解了神经网络算法，后在网络金融课分享了鱼书的ppt，得知金融方面的非结构信息常用深度学习算法，之后阅读过二十几本人工智能相关书籍，在20年用4个月自学完了《动手学深度学习》预览版并动手翻译了GAN从MXNet到PyTorch&amp;TF2;DCGAN从MXNet到PyTorch，复现PyTorch、DJL等一系列深度学习移动端框架的Demo。</li><li>研报工作方面：用Docker部署成《To be AI PM》里记述AI行业研究、AI公司研究。并目标为了致力于用AI处理生出金融研报。</li></ul><p>简历更多，见<a href="https://stevenjokess.github.io/" target="_blank" rel="noreferrer">https://stevenjokess.github.io/</a></p><hr><p><a href="https://www.bilibili.com/video/BV1Gh411B7BP?from=search&amp;seid=3264429653708151447" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Gh411B7BP?from=search&amp;seid=3264429653708151447</a></p><p>求职AI跳绳产品经理，简历见：<a href="https://stevenjokess.github.io/2bPM/get_started.html%EF%BC%9B%E9%82%AE%E7%AE%B1%EF%BC%9Allgg8679@qq.com" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/get_started.html；邮箱：llgg8679@qq.com</a></p><ul><li>健身方面：跳绳比赛成绩:30s单摇:66;30s双摇:60;三摇:11个;·在4*30男子团体单摇比赛,作为非体院唯一绳没断的第四棒,团体一同跳250.取得市和省级铜牌。·随后,作为非社团成员,文案宣传跳绳燃脂效率高、方便,招新翻四倍。还有初级教练、裁判证;曾会单手俯卧撑、深蹲10个+；</li><li>AI方面：我的整个经历，大一参加数学建模了解了神经网络算法，后在网络金融课分享了鱼书的ppt，得知金融方面的非结构信息常用深度学习算法，之后阅读过二十几本人工智能相关书籍，在20年用4个月自学完了《动手学深度学习》预览版并预览版并动手翻译了GAN从MXNet到PyTorch&amp;TF2;DCGAN从MXNet到PyTorch，复现PyTorch、DJL等一系列深度学习移动端框架的Demo。</li><li>产品经理方面：虽然没有工作经历，但还是努力修炼了一系列的能力。战略能力上，在百度一面失败后，考虑到了百度开发者版的想法。沟通能力上，与MXNet的开发者交流无人社区冷淡情况。学习上，学习十余本产品有关的书，并自行总结了AI产品经理的工作内容和技能要求，用Docker部署成《To be AI PM》书。</li></ul><hr><p>求职AI金融/跳绳产品经理，简历见：<a href="https://stevenjokess.github.io/2bPM/get_started.html%EF%BC%9B%E9%82%AE%E7%AE%B1%EF%BC%9Allgg8679@qq.com" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/get_started.html；邮箱：llgg8679@qq.com</a></p><ul><li>金融方面：2020届的山西大学金融学专业的毕业生，获得三好学生学业奖学金，拥有会计、证券、基金从业证书，毕业论文是用Python的Statsmodel库里的VAR模型完成的《中美股市的联动性分析》，提出百度股价被低估能上300USD的想法，实现后。现注意到百度股票主打AI第一股重新去香港上市。ToB和ToG业务强调服务,要随时响应客户需求，我的金融背景能快速学会用客户的语言进行业务沟通。<a href="https://cloud.ofweek.com/news/2020-11/ART-178801-8500-30469911.html" target="_blank" rel="noreferrer">8</a></li><li>AI方面：我的整个经历，大一参加数学建模了解了神经网络算法，后在网络金融课分享了鱼书的ppt，得知金融方面的非结构信息常用深度学习算法，之后阅读过二十几本人工智能相关书籍，在20年用4个月自学完了《动手学深度学习》预览版并动手翻译MXNet到PyTorch的GAN\\DCGAN，复现PyTorch、DJL等一系列深度学习移动端框架的Demo。</li><li>产品经理方面：虽然没有工作经历，但还是努力修炼了一系列的能力。战略能力上，在百度一面失败后，考虑到了百度开发者版的想法。沟通能力上，与MXNet的开发者交流无人社区冷淡情况。学习上，学习十余本产品有关的书，并自行总结了AI产品经理的工作内容和技能要求，用Docker部署成《To be AI PM》书</li><li>跳绳方面：比赛成绩:30s单摇:66;30s双摇:60;三摇:11个;·在4*30男子团体单摇比赛,作为非体院唯一绳没断的第四棒,团体一同跳250.取得市和省级铜牌。·随后,作为非社团成员,文案宣传跳绳燃脂效率高、方便,招新翻四倍。还有初级教练、裁判证;</li></ul><hr><p>求职一份AI产品经理</p><ul><li>金融方面：2020届的山西大学金融学专业的毕业生，获得三好学生学业奖学金，拥有会计、证券、基金从业证书，毕业论文是用Python的Statsmodel库里的VAR模型完成的《中美股市的联动性分析》，提出百度股价被低估能上300USD的想法，实现后。现注意到百度股票主打AI第一股重新去香港上市。ToB和ToG业务强调服务,要随时响应客户需求，我的金融背景能快速学会用客户的语言进行业务沟通。<a href="https://cloud.ofweek.com/news/2020-11/ART-178801-8500-30469911.html" target="_blank" rel="noreferrer">8</a></li><li>AI方面：我的整个经历，大一参加数学建模了解了神经网络算法，后在网络金融课分享了鱼书的ppt，得知金融方面的非结构信息常用深度学习算法，之后阅读过二十几本人工智能相关书籍，在20年用4个月自学完了《动手学深度学习》预览版并动手翻译MXNet到PyTorch的GAN\\DCGAN，复现PyTorch、DJL等一系列深度学习移动端框架的Demo。</li><li>产品经理方面：虽然没有工作经历，但还是努力修炼了一系列的能力。战略能力上，在百度一面失败后，考虑到了百度开发者版的想法。沟通能力上，与MXNet的开发者交流无人社区冷淡情况。学习上，学习十余本产品有关的书，并自行总结了AI产品经理的工作内容和技能要求，用Docker部署成《To be AI PM》书。</li><li>健身方面：跳绳比赛成绩:30s单摇:66;30s双摇:60;三摇:11个;·在4*30男子团体单摇比赛,作为非体院唯一绳没断的第四棒,团体一同跳250.取得市和省级铜牌。·随后,作为非社团成员,文案宣传跳绳燃脂效率高、方便,招新翻四倍。还有初级教练、裁判证;曾会单手俯卧撑、深蹲10个+；<a href="https://www.bilibili.com/video/BV1Gh411B7BP?from=search&amp;seid=3264429653708151447" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Gh411B7BP?from=search&amp;seid=3264429653708151447</a></li></ul><p>简历见：<a href="https://stevenjokess.github.io/2bPM/get_started.html%EF%BC%9B" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/get_started.html；</a> 邮箱：llgg8679@qq.com； AI时代批判与共产主义意识形态输出：<a href="https://stevenjokess.github.io/2bPM/AI_critical.html" target="_blank" rel="noreferrer">https://stevenjokess.github.io/2bPM/AI_critical.html</a></p><h3 id="百度aistudio面试" tabindex="-1">百度aistudio面试 <a class="header-anchor" href="#百度aistudio面试" aria-label="Permalink to &quot;百度aistudio面试&quot;">​</a></h3><p>当时是问了我常用的框架，我说PyTorch，一个是学术开源的多，一个是官方论坛讨论的多。后来我反思应该把这种关系说成飞轮效应，相互促进。</p><p>后面接连问了几个问题，我当时没反应和记忆过来，后来发现应该是考虑需求收集的能力，应该备纸笔来辅助记忆。</p><p>后面面试官提到应该做些项目来锻炼我的产品思维，并给我推荐了《产品方法论》。</p><p><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/aistudio-job.md" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/aistudio-job.md</a></p><h3 id="说服szha开放评论区" tabindex="-1">说服szha开放评论区 <a class="header-anchor" href="#说服szha开放评论区" aria-label="Permalink to &quot;说服szha开放评论区&quot;">​</a></h3><p><a href="https://github.com/apache/incubator-mxnet/issues/18931" target="_blank" rel="noreferrer">https://github.com/apache/incubator-mxnet/issues/18931</a></p><p><img src="'+o+'" alt="评论区的问题"></p><p>1、摆数据</p><p>我会拿出相关数据来证明改动的必要性，数据可以是页面的点击数、用户的跳出率等。</p><p>截了PyTorch论坛的图，肉眼可见地他们的论坛运营很活跃，几乎每个问题都有人回答。几乎每个问题都有人回答，而对比MXNet的论坛，几个月都没几个问题，而且问题几乎没人回答都烂尾的。</p><p>2、讲事实</p><p>其次，我会讲事实。在数据论证的基础上陈述项目规划目标和领导预期，并结合所要改动的功能点进行说明，论证修改后会获得双方共赢的良好效果。</p><p>3、适当妥协</p><p>我会理解技术拒绝更改的原因，然后在合理的范围内做适当的妥协，如在不影响大局的前提下，适当的延长项目时间等，关键是项目有所输出并保证质量。</p><p>4、向上沟通</p><p>最后，向上沟通，如果基础的沟通无效，不妨将双方的leader加入到沟通的过程中，通过邮件或者是微信等一些实时沟通的方式，条理清晰的陈述己方的观点，并让leader做最后评判。</p><p>后来加了他的微信，说了两个关键点：一个是保证问题解决，一个是时间要尽快。</p><p>5、复盘</p><p>在处理本次冲突的基础上，还是要客观的分析冲突产生的原因是由于沟通机制存在问题，还是由于双方的沟通方式没有磨合好，PM需要根据实际情况提出积极的解决方案，提前规避下次的冲突产生。在很多同类型的沟通问题中也确实存在由于PM的思考不严谨，需求频繁更改的情况，如果确实是此类原因导致的沟通不顺畅，那么及时反思和承认错误也是必要的，没有一成不变的沟通方式，良好的沟通应该是在双方的理解和信任的基础上不断完善的。”</p><p>后来加了他的微信，说了两个关键点：一个是保证问题解决，一个是时间要尽快。</p><p>不过一切StevenJokes的记录，都因为一次情绪崩溃而丧失。</p><h3 id="心态崩溃的原因" tabindex="-1">心态崩溃的原因 <a class="header-anchor" href="#心态崩溃的原因" aria-label="Permalink to &quot;心态崩溃的原因&quot;">​</a></h3><ul><li>校招社招两头为难：由于疫情没能实习和春招，错过应届生省份，又想转行AI。</li><li>家里催的急引发的稀缺心态：由于家里经济条件不好会导致大脑的注意力被稀缺资源俘获。过度关注当前利益而无法考虑长远利益，使得过于抒发了负面zs情绪<a href="https://www.zhihu.com/question/20791021/answer/652756690" target="_blank" rel="noreferrer">2</a></li><li>感觉未来就业无望：由于并非名校，且金融专业尤其看学历和背景。</li></ul><p>所以，心态崩溃根本原因是对人生未来的迷茫无助、家庭的经济能力差导致的，如果有一份较为稳定光明的工作，比如这份工作，我的<strong>情绪控制能力</strong>还是可以的，毕竟，没几个能在家里承受压力憋将近一年去修炼技能的。</p><h2 id="gan、dcgan" tabindex="-1">GAN、DCGAN <a class="header-anchor" href="#gan、dcgan" aria-label="Permalink to &quot;GAN、DCGAN&quot;">​</a></h2><ul><li><a href="https://preview.d2l.ai/d2l-en/master/chapter_generative-adversarial-networks/gan.html" target="_blank" rel="noreferrer">https://preview.d2l.ai/d2l-en/master/chapter_generative-adversarial-networks/gan.html</a></li><li><a href="https://preview.d2l.ai/d2l-en/master/chapter_generative-adversarial-networks/dcgan.html" target="_blank" rel="noreferrer">https://preview.d2l.ai/d2l-en/master/chapter_generative-adversarial-networks/dcgan.html</a></li></ul><p>部分测试：</p><p>GAN:</p><ul><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/my5gan.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/my5gan.ipynb</a></li><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/D_block_ok.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/D_block_ok.ipynb</a></li><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/G_block1.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/G_block1.ipynb</a></li><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/gan_torch.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/gan_torch.ipynb</a></li></ul><p>DCGAN:</p><ul><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/dcgan_torch5.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/dcgan_torch5.ipynb</a></li><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/dcgan_train1.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/dcgan_train1.ipynb</a></li><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/dcgan_pt3.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/dcgan_pt3.ipynb</a></li><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/dcgan_n2train.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/dcgan_n2train.ipynb</a></li><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/colab_pt_DCGAN/DCGAN_ptlr5.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/chapter-generative-adversarial-networks/colab_pt_DCGAN/DCGAN_ptlr5.ipynb</a></li></ul><p>之前测试的：</p><ul><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/Ch17_GAN/17-1pt.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/Ch17_GAN/17-1pt.ipynb</a></li><li><a href="https://github.com/StevenJokess/d2l-en-read/blob/moreme/Ch17_GAN/17-2pt.ipynb" target="_blank" rel="noreferrer">https://github.com/StevenJokess/d2l-en-read/blob/moreme/Ch17_GAN/17-2pt.ipynb</a></li></ul><p>虽然我的commit记录没了，但我的记录就是原#@tab pytorch里的内容</p><ul><li><a href="https://github.com/d2l-ai/d2l-en/pull/1400" target="_blank" rel="noreferrer">https://github.com/d2l-ai/d2l-en/pull/1400</a></li><li><a href="https://github.com/d2l-ai/d2l-en/pull/1422" target="_blank" rel="noreferrer">https://github.com/d2l-ai/d2l-en/pull/1422</a></li></ul><p>我解释情绪与mli、astonzhang沟通：<a href="https://github.com/d2l-ai/d2l-en/pull/1449" target="_blank" rel="noreferrer">https://github.com/d2l-ai/d2l-en/pull/1449</a></p><h3 id="为什么选择这一行" tabindex="-1">为什么选择这一行 <a class="header-anchor" href="#为什么选择这一行" aria-label="Permalink to &quot;为什么选择这一行&quot;">​</a></h3><p>我即是产品，一个好的产品是&quot;要、能、赚！&quot;</p><ul><li>社会需要：对比大量的金融从业人员，真的AI产品经理是价值很大且稀缺的，AI产品由于代码、模型的分发边际成本低，可能影响上亿的人。</li><li>能力胜任：金融行业知识（更好与开发交流开发背景）、编程AI知识（更好协调开发）、产品经理知识（做好项目管理）。</li><li>回报丰厚：物质生活上，有稳定较为丰厚的现金流来维持生活；精神生活上，能满足我对于AI本身的向往追求，实现自我价值。</li></ul><h3 id="职业规划" tabindex="-1">职业规划 <a class="header-anchor" href="#职业规划" aria-label="Permalink to &quot;职业规划&quot;">​</a></h3><ul><li>短期：把眼前的事情做得足够的扎实，修炼产品经理的技能。</li><li>中短期（3-5年）：职位从产品经理到高级产品经理（对<strong>金融智能投研业务</strong>有通盘的了解）最好能到产品总监（整合各方面的资源，在商业上帮助公司）的位置。</li><li>中长期（7+年）：在中短期的人脉行业积累下，锻炼嗅觉，去做投资，帮助更多企业和青年人成长。</li></ul><h3 id="你能给公司带来什么价值" tabindex="-1">你能给公司带来什么价值 <a class="header-anchor" href="#你能给公司带来什么价值" aria-label="Permalink to &quot;你能给公司带来什么价值&quot;">​</a></h3><p>TODO:</p><h3 id="对小冰的认知" tabindex="-1">对小冰的认知 <a class="header-anchor" href="#对小冰的认知" aria-label="Permalink to &quot;对小冰的认知&quot;">​</a></h3><ul><li>chatbot：与C端用户聊天，这一点考虑到情感是不做商业化。</li><li>艺术教育：和有声读物去版权合作、画家6个虚拟人格办画展、小冰机智过人里根据诗词作曲。</li></ul><p><strong>基于深度学习的自然语言生成</strong>在金融领域的应用</p><ul><li>智能投研：在金融领域，小冰是目前<strong>全球范围内规模第一的金融文本摘要生成</strong>平台。去试图保证了稳定性、准确性以及时效性，特别是上市公告高并发、非密集的时候可以大大减压。万得资讯 ToB</li><li>金融风控：基于小冰人工智能技术生成的文本、大数据金融知识图谱来做风控。</li><li>金融资讯：实时翻译来提供中英双语AI金融资讯，每日经济新闻、华尔街见闻。ToC</li></ul><p>业务扩展：短、长摘要；金融研报；垂直搜索；知识图谱；全景可视化</p><p><img src="'+n+'" alt="微软小冰在金融7"></p><p><a href="https://github.com/StevenJokess/2bPM/blob/master/chapter_company/xiaoice.md" target="_blank" rel="noreferrer">https://github.com/StevenJokess/2bPM/blob/master/chapter_company/xiaoice.md</a></p><h2 id="准备提问" tabindex="-1">准备提问 <a class="header-anchor" href="#准备提问" aria-label="Permalink to &quot;准备提问&quot;">​</a></h2><h3 id="官网的问题" tabindex="-1">官网的问题 <a class="header-anchor" href="#官网的问题" aria-label="Permalink to &quot;官网的问题&quot;">​</a></h3><p><a href="https://e.xiaoice.com/Home?r=%2F" target="_blank" rel="noreferrer">https://e.xiaoice.com/Home?r=%2F</a></p><ul><li>为何不是HTTPS且自动转向HTTPS？安全需求</li><li>初次领养时，验证码错误不提示，反而在登录才会出现？异常流程的问题。</li><li>直接登录也可以手机验证码领养，那为何要多个领养的注册界面标签？多余流程的问题</li><li>名字不能超过10个字，为啥不早提示？异常流程没有提前告诉。</li><li>可以用“………………………………”做名字？如果传唤怎么传？可用性需求</li><li>QQ手机APP，搜索并关注公众号“小冰”（ID：ms-xiaoice）</li><li>在微信中关注公众号“小冰”（ID: xiaoice-ms），激活小冰。</li><li>我是古灵精怪的人工智能少女小冰，我来自微软。<a href="https://www.yeelight.com/zh_CN/product/donut" target="_blank" rel="noreferrer">6</a></li><li>哄情绪低落的人类开心起来，来避免冲动投资与撤资。<a href="https://www.bilibili.com/video/av796273602/" target="_blank" rel="noreferrer">5</a></li></ul><p><img src="'+s+'" alt="小冰Moka招聘界面4"></p><h3 id="小冰框架-5" tabindex="-1">小冰框架 <a href="https://www.bilibili.com/video/av796273602/" target="_blank" rel="noreferrer">5</a> <a class="header-anchor" href="#小冰框架-5" aria-label="Permalink to &quot;小冰框架 [5]&quot;">​</a></h3><ul><li>登录：要先注册不明显</li><li>注册必须要密码，而登录却可以只靠验证码</li><li>没有更改手机</li><li>注册界面 <a href="https://www.yeelight.com/zh_CN/product/donut" target="_blank" rel="noreferrer">6</a>：还是© 2020 Microsoft。 4月8日已经变了。</li><li>是否可以从金融专业的翻译入手<a href="https://www.youtube.com/watch?v=vu6YmD5TX7E" target="_blank" rel="noreferrer">7</a></li><li><a href="https://singer.xiaoice.com/:" target="_blank" rel="noreferrer">https://singer.xiaoice.com/:</a> 大小约140M ； <a href="http://xstudio.pub/" target="_blank" rel="noreferrer">http://xstudio.pub/</a> 大小约220M</li></ul><p><img src="'+h+'" alt="建议的登录界面"></p><h2 id="boss面" tabindex="-1">Boss面 <a class="header-anchor" href="#boss面" aria-label="Permalink to &quot;Boss面&quot;">​</a></h2><p>行业的发展情况、产业链的发展、整体行业发展的大趋势类的话题，以及聊一下跟公司的文化价值观、愿景，看你是否认同公司的文化，如果能聊到共性，产生共鸣<a href="https://t.qidianla.com/1165227.html" target="_blank" rel="noreferrer">3</a></p>',95)])])}const f=r(p,[["render",b]]);export{_ as __pageData,f as default};
